SELECT UTC_TIMESTAMP(3) AS observed_utc;
SELECT g.account_id,g.task_id,t.status task_status,g.group_execution_id,g.role_type,g.availability_status,g.occupied_at,g.released_at FROM pull_task_group_account g JOIN pull_task t ON t.id=g.task_id AND t.tenant_id=g.tenant_id WHERE g.account_id IN(821,999,1038) ORDER BY g.id;
SELECT 'marketing_account_occupancy' source,account_id,marketing_task_id,occupied_at FROM marketing_account_occupancy WHERE account_id IN(821,999,1038);
SELECT 'group_pull_marketing_execution' source,id,task_id,builder_account_id,marketing_account_id,execution_status,released_at FROM group_pull_marketing_execution WHERE (builder_account_id IN(821,999,1038) OR marketing_account_id IN(821,999,1038)) AND released_at IS NULL;
SELECT 'hyperlink_task_round_account' source,h.id,h.hyperlink_task_id,h.account_id,h.assignment_status,h.released_at,r.run_status FROM hyperlink_task_round_account h JOIN hyperlink_task_runtime r ON r.hyperlink_task_id=h.hyperlink_task_id WHERE h.account_id IN(821,999,1038) AND h.released_at IS NULL;
SELECT t.id,t.status,t.creation_mode,s.creator_group_id,s.manager_group_id,s.puller_group_id,s.station_group_id FROM pull_task t JOIN pull_task_standard_setting s ON s.task_id=t.id AND s.tenant_id=t.tenant_id WHERE t.deleted_at IS NULL AND t.status NOT IN('COMPLETED','ENDED') AND (s.creator_group_id IN(658,659,664) OR s.manager_group_id IN(658,659,664) OR s.puller_group_id IN(658,659,664) OR s.station_group_id IN(658,659,664));
SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('feed_task','feed_task_account','contact_friend_task','contact_friend_task_account','normal_group_creation_item','normal_group_creation_task','group_creation_marketing_item','group_creation_marketing_task','join_task','join_task_result','group_data_package','group_data_package_import','data_package','data_package_import','account_credential') ORDER BY table_name,ordinal_position;
